// Aufruf des Portals prüfen und aufbereiten (einmal für alle Elemente).
// Der Workflow kennt keine Postfächer und keine festen Adressen: Absender-Postfach, Empfänger und Anhänge bestimmt das Portal.
const b = $input.first().json.body ?? {};
const EMAIL = /^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/;
const fehler = [];

const modus = String(b.modus ?? 'senden').trim();
if (!['senden', 'entwurf', 'pruefen'].includes(modus)) fehler.push(`Unbekannter Modus „${modus}“ (erlaubt: senden, entwurf, pruefen).`);
const absender = String(b.absender ?? '').trim();
if (absender && !EMAIL.test(absender)) fehler.push(`Absender-Postfach „${absender}“ ist keine gültige Adresse.`);
if (!absender && modus !== 'pruefen') fehler.push('Absender-Postfach fehlt.');

/** „a@b, Name <c@d>“ oder Liste → Empfänger im Format von Microsoft Graph */
function empfaenger(roh, feld, nr) {
  const teile = (Array.isArray(roh) ? roh : String(roh ?? '').split(/[,;]/)).map((x) => String(x ?? '').trim()).filter(Boolean);
  const liste = [];
  for (const t of teile) {
    const m = /^(.*)<([^<>]+)>$/.exec(t);
    const address = (m ? m[2] : t).trim();
    const name = m ? m[1].trim().replace(/^"|"$/g, '') : '';
    if (!EMAIL.test(address)) { fehler.push(`E-Mail ${nr}: ungültige Adresse „${t}“ im Feld „${feld}“.`); continue; }
    liste.push({ emailAddress: name ? { address, name } : { address } });
  }
  return liste;
}

// Anhang-Vorrat: jede Datei einmal im Aufruf, die E-Mails nennen nur die Kennungen
const vorrat = new Map();
let bytes = 0;
(Array.isArray(b.anhaenge) ? b.anhaenge : []).forEach((a, i) => {
  const id = String(a?.id ?? '').trim();
  const dateiname = String(a?.dateiname ?? '').trim();
  const inhalt = String(a?.inhalt_base64 ?? '');
  if (!id) { fehler.push(`Anhang ${i + 1}: Kennung fehlt.`); return; }
  if (vorrat.has(id)) { fehler.push(`Anhang-Kennung „${id}“ ist doppelt.`); return; }
  if (!dateiname) { fehler.push(`Anhang „${id}“: Dateiname fehlt.`); return; }
  if (!inhalt.trim()) { fehler.push(`Anhang „${dateiname}“ ist leer.`); return; }
  const groesse = Math.floor(inhalt.length * 3 / 4);
  bytes += groesse;
  vorrat.set(id, { id, dateiname, mime: String(a?.mime ?? '').trim() || 'application/octet-stream', groesse });
});

const mails = [];
(Array.isArray(b.mails) ? b.mails : []).forEach((m, i) => {
  const nr = Number.isInteger(m?.nr) ? m.nr : i + 1;
  const an = empfaenger(m?.an, 'an', nr);
  const cc = empfaenger(m?.cc, 'cc', nr);
  const bcc = empfaenger(m?.bcc, 'bcc', nr);
  const antwort_an = empfaenger(m?.antwort_an, 'antwort_an', nr);
  if (!an.length) fehler.push(`E-Mail ${nr}: kein Empfänger.`);
  const betreff = String(m?.betreff ?? '').trim();
  if (!betreff) fehler.push(`E-Mail ${nr}: Betreff fehlt.`);
  const ids = Array.isArray(m?.anhaenge) ? m.anhaenge.map((x) => String(x)) : [];
  for (const id of ids) if (!vorrat.has(id)) fehler.push(`E-Mail ${nr}: unbekannter Anhang „${id}“.`);
  mails.push({ nr, rolle: String(m?.rolle ?? ''), an, cc, bcc, antwort_an, betreff, text: String(m?.text ?? ''), html: m?.text_format === 'html', anhaenge: ids });
});
if (modus !== 'pruefen' && !mails.length) fehler.push('Der Aufruf enthält keine E-Mail.');
if (mails.length > 20) fehler.push('Höchstens 20 E-Mails je Aufruf.');
if (new Set(mails.map((m) => m.nr)).size !== mails.length) fehler.push('Die Nummern der E-Mails sind nicht eindeutig.');

return [{ json: {
  ok: !fehler.length, fehler: fehler.join(' '), modus, absender,
  postfach_pruefen: modus === 'pruefen' && !!absender,
  anwendung: String(b.anwendung ?? ''), objekt: String(b.objekt ?? ''), benutzer: String(b.benutzer ?? ''),
  mails, anhaenge: [...vorrat.values()], anhang_bytes: bytes,
} }];

// Je E-Mail ein Element mit der fertigen Nachricht für Microsoft Graph (Anhänge aus dem gemeinsamen Vorrat).
const p = $('Aufruf prüfen').first().json;
const roh = $('Webhook Portal').first().json.body.anhaenge ?? [];
const inhalt = new Map(roh.map((a) => [String(a.id ?? '').trim(), String(a.inhalt_base64 ?? '').replace(/^data:[^,]*,/, '').replace(/\s+/g, '')]));
const meta = new Map(p.anhaenge.map((a) => [a.id, a]));

return p.mails.map((m) => ({ json: {
  nr: m.nr, rolle: m.rolle, absender: p.absender,
  an: m.an.map((e) => e.emailAddress.address).join(', '),
  nachricht: {
    subject: m.betreff,
    body: { contentType: m.html ? 'HTML' : 'Text', content: m.text },
    toRecipients: m.an, ccRecipients: m.cc, bccRecipients: m.bcc,
    ...(m.antwort_an.length ? { replyTo: m.antwort_an } : {}),
    attachments: m.anhaenge.map((id) => ({
      '@odata.type': '#microsoft.graph.fileAttachment',
      name: meta.get(id).dateiname, contentType: meta.get(id).mime, contentBytes: inhalt.get(id),
    })),
  },
} }));

// Ergebnis von „Entwurf anlegen“ je E-Mail auswerten. Liefert genau EIN Element, damit der Versand danach nur einmal läuft.
const p = $('Aufruf prüfen').first().json;
const mails = $('E-Mails aufteilen').all();
const antworten = $input.all();

/** Klartext für eine Ablehnung durch Microsoft Graph */
function graphFehler(a, schritt) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  let hinweis = '';
  if (s === 401) hinweis = ' Die Zugangsdatei „Euroflex Microsoft Graph“ in n8n ist ungültig oder der Clientschlüssel abgelaufen.';
  else if (s === 403) hinweis = ' Die App darf dieses Postfach nicht verwenden (Berechtigung Mail.ReadWrite/Mail.Send bzw. Bereich in Exchange prüfen).';
  else if (s === 404) hinweis = ' Das Postfach gibt es in Microsoft 365 nicht oder es liegt außerhalb des erlaubten Bereichs.';
  else if (s === 413) hinweis = ' Die Anhänge sind zu groß für einen Aufruf.';
  return `${schritt} fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh}${hinweis}`;
}

const stand = mails.map((m, i) => {
  const a = (antworten[i] && antworten[i].json) || {};
  const ok = a.statusCode === 201 && a.body && a.body.id;
  return {
    nr: m.json.nr, rolle: m.json.rolle, an: m.json.an,
    entwurf_id: ok ? a.body.id : null,
    message_id: ok ? a.body.internetMessageId ?? '' : '',
    fehler: ok ? '' : graphFehler(a, 'Entwurf anlegen'),
  };
});

return [{ json: {
  modus: p.modus, absender: p.absender, mails: stand,
  sendbar: p.modus === 'senden' ? stand.filter((s) => s.entwurf_id).length : 0,
} }];

// Je angelegtem Entwurf ein Element für „Senden“.
const s = $input.first().json;
return s.mails.filter((m) => m.entwurf_id).map((m) => ({ json: { nr: m.nr, absender: s.absender, entwurf_id: m.entwurf_id } }));

// Antwort an das Portal: Status je E-Mail und Gesamtstatus.
const st = $('Entwürfe auswerten').first().json;
let auftraege = [];
let gesendet = [];
if (st.sendbar > 0) {
  auftraege = $('Sendbare aufteilen').all();
  gesendet = $('Senden').all();
}
const zeitpunkt = new Date().toISOString();

function sendeFehler(a) {
  const s = a.statusCode;
  const e = a.body && typeof a.body === 'object' ? a.body.error : null;
  const roh = e ? `${e.code ?? ''}: ${e.message ?? ''}`.replace(/^: /, '') : String((a.error && (a.error.message || a.error)) || (typeof a.body === 'string' ? a.body : '') || 'keine Antwort').slice(0, 300);
  return `Senden fehlgeschlagen${s ? ` (HTTP ${s})` : ''}: ${roh} Der Entwurf liegt im Postfach unter „Entwürfe“.`;
}

const mails = st.mails.map((m) => {
  const basis = { nr: m.nr, rolle: m.rolle, an: m.an };
  if (!m.entwurf_id) return { ...basis, status: 'fehler', fehler: m.fehler };
  if (st.modus !== 'senden') return { ...basis, status: 'entwurf', message_id: m.message_id, zeitpunkt };
  const i = auftraege.findIndex((a) => a.json.nr === m.nr);
  const a = (i >= 0 && gesendet[i] && gesendet[i].json) || {};
  if (a.statusCode === 202) return { ...basis, status: 'gesendet', message_id: m.message_id, zeitpunkt };
  return { ...basis, status: 'fehler', fehler: sendeFehler(a), entwurf_im_postfach: true };
});

const gut = mails.filter((m) => m.status !== 'fehler').length;
const status = gut === mails.length ? (st.modus === 'senden' ? 'gesendet' : 'entwurf') : gut ? 'teilweise' : 'fehler';
return [{ json: { antwort: {
  status, postfach: st.absender, zeitpunkt, mails,
  fehler: mails.filter((m) => m.status === 'fehler').map((m) => `E-Mail ${m.nr}: ${m.fehler}`).join(' '),
} } }];
